add_filter( 'woocommerce_product_related_products_heading', 'perfectpixel_related_heading' );
add_filter( 'woocommerce_product_loop_start', 'perfectpixel_related_subheading' );

function perfectpixel_related_heading( $heading ) {
	$custom = trim( '{{related_heading}}' );
	return '' !== $custom ? $custom : $heading;
}

function perfectpixel_related_subheading( $html ) {
	$text = trim( '{{related_subheading}}' );
	if ( '' !== $text && 'related' === wc_get_loop_prop( 'name' ) ) {
		$html = '<p class="perfectpixel-related-subheading">' . esc_html( $text ) . '</p>' . $html;
	}
	return $html;
}
